export const deleteV1AddressesAddressIdRoute = createRoute({
  method: 'delete',
  path: '/V1/addresses/{addressId}',
  tags: ['addresses/{addressId}'],
  summary: 'addresses/{addressId}',
  description: 'Delete customer address by ID.',
  operationId: 'customerAddressRepositoryV1DeleteByIdDelete',
  request: {
    params: z.object({
      addressId: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: { in: 'path', name: 'addressId', required: true, schema: { type: 'integer' } },
        }),
    }),
  },
  responses: {
    200: {
      description: '200 Success.',
      content: {
        'application/json': { schema: z.boolean().openapi({ description: 'true on success' }) },
        'application/xml': { schema: z.boolean().openapi({ description: 'true on success' }) },
      },
    },
    400: {
      description: '400 Bad Request',
      content: {
        'application/json': { schema: ErrorResponseSchema },
        'application/xml': { schema: ErrorResponseSchema },
      },
    },
    401: {
      description: '401 Unauthorized',
      content: {
        'application/json': { schema: ErrorResponseSchema },
        'application/xml': { schema: ErrorResponseSchema },
      },
    },
    500: {
      description: 'Internal Server error',
      content: {
        'application/json': { schema: ErrorResponseSchema },
        'application/xml': { schema: ErrorResponseSchema },
      },
    },
    default: {
      description: 'Unexpected error',
      content: {
        'application/json': { schema: ErrorResponseSchema },
        'application/xml': { schema: ErrorResponseSchema },
      },
    },
  },
})

