export const getV1ProductsSkuRoute = createRoute({
  method: 'get',
  path: '/V1/products/{sku}',
  tags: ['products/{sku}'],
  summary: 'products/{sku}',
  description: 'Get info about product by product SKU',
  operationId: 'catalogProductRepositoryV1GetGet',
  request: {
    params: z.object({
      sku: z
        .string()
        .openapi({
          param: { in: 'path', name: 'sku', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      editMode: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'editMode', required: false, schema: { type: 'boolean' } },
        }),
      storeId: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'storeId', required: false, schema: { type: 'integer' } },
        }),
      forceReload: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: { in: 'query', name: 'forceReload', required: false, schema: { type: 'boolean' } },
        }),
    }),
  },
  responses: {
    200: {
      description: '200 Success.',
      content: {
        'application/json': { schema: CatalogDataProductInterfaceSchema },
        'application/xml': { schema: CatalogDataProductInterfaceSchema },
      },
    },
    400: {
      description: '400 Bad Request',
      content: {
        'application/json': { schema: ErrorResponseSchema },
        'application/xml': { schema: ErrorResponseSchema },
      },
    },
    401: {
      description: '401 Unauthorized',
      content: {
        'application/json': { schema: ErrorResponseSchema },
        'application/xml': { schema: ErrorResponseSchema },
      },
    },
    default: {
      description: 'Unexpected error',
      content: {
        'application/json': { schema: ErrorResponseSchema },
        'application/xml': { schema: ErrorResponseSchema },
      },
    },
  },
})

